S=/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad; git show e5414f5bf:explorations/fortress-gap-ledger.md > $S/ledger-base.md; cp explorations/fortress-gap-ledger.md $S/ledger-head.md; python3 - <<'EOF'
import re
S='/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad'
b=open(S+'/ledger-base.md').read().split('\n'); h=open(S+'/ledger-head.md').read().split('\n')
def rows(lines):
    d={}
    for i,l in enumerate(lines):
        m=re.match(r'^\| (\d+\.?) \|',l)
        if m: d.setdefault(m.group(1),[]).append((i+1,l))
    return d
rb,rh=rows(b),rows(h)
for k in rh:
    if len(rh[k])>1: print('DUP',k,[x[0] for x in rh[k]])
for k in rb:
    if k not in rh: print('DELETED',k)
for k in rh:
    if k not in rb: print('NEW',k,rh[k][0][0]); continue
    ob=rb[k][0][1]; nh=rh[k][0][1]
    if ob==nh: continue
    oc=ob.split(' | '); nc=nh.split(' | ')
    print('CHANGED',k,'line',rh[k][0][0],'cells',len(oc),len(nc))
    for i,(o,n) in enumerate(zip(oc,nc)):
        if o==n: continue
        if n.startswith(o.rstrip(' |')): print('   cell',i,'appended',len(n)-len(o))
        else: print('   cell',i,'REWRITTEN\n     OLD:',o[:300],'\n     NEW:',n[:300])
# order of numeric rows in head
nums=[(int(k),v[0][0]) for k,v in rh.items() if not k.endswith('.')]
nums.sort(key=lambda x:x[1])
prev=0
for n,l in nums:
    if n<prev: print('OUT OF ORDER',n,'at',l,'after',prev)
    prev=max(prev,n)
print('max row',max(n for n,_ in nums))
allnums=set(n for n,_ in nums)
print('missing', [i for i in range(1,max(allnums)+1) if i not in allnums])
EOF

